// Conan: registers DuckDB's statically linked extensions and capabilities before main (DuckDB >= 2.0.0).
// duckdb_register_static_extensions() is generated by DuckDB's build for the extensions it links; upstream compiles
// it together with extension/loader/static_extension_autoregister.cpp into each program. Here both are in the
// duckdb_static_extension_loader library, and the recipe force-links this translation unit through the anchor below,
// so the registration also runs in programs that link the static libraries.
#include <stdint.h>

extern "C" int32_t duckdb_register_static_extensions(void);

extern "C" {
int duckdb_static_extension_loader_anchor = 0;
}

namespace {
struct ConanStaticExtensionLoader {
	ConanStaticExtensionLoader() {
		duckdb_register_static_extensions();
	}
};
const ConanStaticExtensionLoader conan_static_extension_loader;
} // namespace
